class ObservationAction(StrictModel):
    request_key:str=Field(pattern=r'^[a-zA-Z0-9_-]{8,80}$')
    expected_revision:int=Field(ge=0)
    action:Literal['confirm','correct','pause','resume','schedule','mark_reviewed','delete','withdraw']
    user_finding:Literal['needs_practice','unsure','understood']|None=None
    note:str=Field(default='',max_length=1000)
    review_in_days:int|None=Field(default=None,ge=0,le=30)

    @model_validator(mode='after')
    def required(self):
        if self.action=='correct' and (not self.note.strip() or self.user_finding is None):raise ValueError('correction_requires_user_reason')
        if self.action=='withdraw' and not self.note.strip():raise ValueError('withdrawal_requires_reason')
        if self.action=='schedule' and self.review_in_days is None:raise ValueError('review_days_required')
        if self.action!='correct' and self.user_finding is not None:raise ValueError('unexpected_user_finding')
        return self


class ReviewPreferences(StrictModel):
    expected_revision:int=Field(ge=0)
    cadence_days:int=Field(default=3,ge=1,le=30)
    daily_limit:int=Field(default=10,ge=1,le=20)
    paused:bool=False
    include_new:bool=True


class LearningPractice(StrictModel):
    request_key:str=Field(pattern=r'^[a-zA-Z0-9_-]{8,80}$')
    expected_revision:int=Field(ge=0)
    mode:Literal['local_demo','llm']='local_demo'
    allow_external_processing:bool=False
    allow_historical_version:bool=False


def withdrawn_questions(db,owner,session_id):
    if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='rw_learning_withdrawals'").fetchone():return set()
    return {r[0] for r in db.execute('SELECT question_id FROM rw_learning_withdrawals WHERE owner_id=? AND session_id=?',(owner,session_id))}


def condition(s,turn,topic,point_id):
    """Recorded conditions only: matching this hash is not independent truth."""
    return {'question':turn.question.prompt,'focus':turn.question.focus_id,'followup':turn.question.followup,
        'point_id':point_id,'rubric':topic.points,'aliases':topic.aliases,
        'references':[r.model_dump(mode='json',exclude={'quote','retrieval_method','supports_claim','independent_truth'}) for r in turn.question.references],
        'version_hash':s.version_hash,'jd_hash':digest(s.jd_text),
        'mode':s.mode,'provider':s.provider,'model':s.model,
        'model_configuration':s.execution.model_identity if s.execution else {'revision':'unknown'},
        'evaluation_method':turn.evaluation.method_version,'assessment_mode':turn.evaluation.assessment_mode}


def observation_payload(s,turn,topic,point_id):
    assessment=next((a for a in turn.evaluation.point_assessments if a.point_id==point_id),None)
    finding=(assessment.status if assessment else 'lexical_located' if point_id in turn.evaluation.covered_ids else 'lexical_not_located')
    data={'session_id':s.session_id,'resume_id':s.resume_id,'version_id':s.version_id,'version_hash':s.version_hash,
        'question_id':turn.question.question_id,'topic_id':topic.anchor_id,'point_id':point_id,
        'knowledge_point':topic.points[point_id],'question':turn.question.prompt,'answer':turn.answer,'answer_hash':digest(turn.answer),
        'finding':finding,'evaluation_note':turn.evaluation.note,'point_assessment':assessment.model_dump() if assessment else None,
        'assessment_mode':turn.evaluation.assessment_mode,'method_version':turn.evaluation.method_version,
        'mode':s.mode,'provider':s.provider,'model':s.model,'observed_at':(turn.answered_at or s.created_at).timestamp(),
        'observation_time_source':'answer_committed_at' if turn.answered_at else 'legacy_session_created_at_fallback',
        'references':condition(s,turn,topic,point_id)['references'],
        'rubric_hash':digest({'points':topic.points,'aliases':topic.aliases}),
        'condition_hash':digest(condition(s,turn,topic,point_id)),
        'independent_mastery':'not_established','personal_experience_truth':'not_verified'}
    return data


def usable_evaluation_source(s,turn,topic):
    """Validate persisted LLM evidence shape without inventing semantic labels."""
    evaluation=turn.evaluation
    if evaluation is None:return False
    if s.mode!='llm':return True
    if not evaluation.has_complete_assessments(topic.points):return False
    correct={a.point_id for a in evaluation.point_assessments if a.status=='correct'}
    covered=evaluation.covered_ids;missing=evaluation.missing_ids
    if len(covered)!=len(set(covered)) or len(missing)!=len(set(missing)):return False
    if set(covered)!=correct or set(missing)!=set(topic.points)-correct:return False
    for assessment in evaluation.point_assessments:
        quote=assessment.answer_quote.strip()
        if (quote and quote not in turn.answer) or (assessment.status!='uncertain' and not quote):return False
    return True


class LearningRepository:
    def __init__(self,workspace,interviews,*,clock=time):
        self.workspace=workspace;self.interviews=interviews;self.clock=clock
        with workspace._connection(write=True) as db:db.executescript(DDL)
        interviews.learning=self

    def _row(self,db,owner,key):
        row=db.execute('SELECT o.*,i.resume_id FROM rw_learning_observations o JOIN rw_interviews i USING(session_id) WHERE observation_id=? AND o.owner_id=?',(key,owner)).fetchone()
        if row is None:raise WorkspaceNotFound('learning_observation_not_found')
        if digest(row['controls'])!=row['controls_hash'] or (row['payload'] and digest(row['payload'])!=row['payload_hash']):raise InvalidProvenance('learning_record_integrity_failed')
        if row['payload']:
            if digest(json.loads(row['payload']))!=row['source_fingerprint']:raise InvalidProvenance('learning_record_integrity_failed')
        elif not json.loads(row['controls']).get('deleted'):raise InvalidProvenance('learning_record_integrity_failed')
        return row

    def _source(self,db,owner,sid,cache):
        if sid not in cache:
            try:
                _,s,v=self.interviews._load(db,owner,sid)
                if s.status!='complete':raise WorkspaceConflict('learning_requires_completed_source')
                cache[sid]=(s,v)
            except (WorkspaceNotFound,WorkspaceConflict,InvalidProvenance):cache[sid]=None
        return cache[sid]

    def _payload_for(self,s,question_id,point_id):
        turn=next((t for t in s.turns if t.question.question_id==question_id),None)
        topic=next((t for t in s.plan if turn and t.anchor_id==turn.question.topic_id),None)
        if not turn or not topic or point_id not in topic.points:return None
        if not usable_evaluation_source(s,turn,topic):return None
        return observation_payload(s,turn,topic,point_id)

    def _view(self,db,owner,row,cache):
        controls=json.loads(row['controls']);now=self.clock()
        base={'observation_id':row['observation_id'],'session_id':row['session_id'],'revision':row['revision'],
            'resume_id':row['resume_id'],
            'created_at':row['created_at'],'confirmed':bool(controls.get('confirmed')),'paused':bool(controls.get('paused')),
            'independent_mastery':'not_established'}
        if controls.get('deleted'):return {**base,'status':'deleted','queue_bucket':'excluded','payload':None,'controls':{}}
        source=self._source(db,owner,row['session_id'],cache)
        if row['question_id'] in withdrawn_questions(db,owner,row['session_id']):
            return {**base,'status':'withdrawn','queue_bucket':'excluded','payload':None,'controls':{},'reason':'evaluation_withdrawn'}
        current=self._payload_for(source[0],row['question_id'],row['point_id']) if source else None
        if not current or digest(current)!=row['source_fingerprint']:
            return {**base,'status':'invalid','queue_bucket':'excluded','payload':None,'controls':{},'reason':'source_unavailable_or_changed'}
        payload=json.loads(row['payload'])
        head=self.workspace._resume(db,owner,payload['resume_id'])['head_version_id']
        historical=head!=payload['version_id']
        expired=now-max(payload['observed_at'],controls.get('checked_at',0))>90*DAY
        bucket=('paused' if controls.get('paused') else 'historical_version' if historical else 'expired' if expired else
            'new' if not controls.get('confirmed') else 'review_due' if controls.get('due_at',now)<=now else 'reviewed')
        return {**base,'status':'expired' if expired else 'valid','queue_bucket':bucket,'payload':payload,'controls':controls,
            'historical_version':historical,'source_age_days':max(0,int((now-payload['observed_at'])/DAY)),
            'confidence':'user_corrected' if controls.get('user_finding') else 'single_observation',
            'reason':{'new':'awaiting_user_check','review_due':'scheduled_time_reached','reviewed':'user_review_scheduled_next',
                'paused':'user_paused','expired':'observation_requires_recheck','historical_version':'resume_head_changed'}[bucket]}

    def get(self,owner,key):
        with self.workspace._connection() as db:return self._view(db,owner,self._row(db,owner,key),{})

    def list(self,owner,*,resume_id=None):
        with self.workspace._connection() as db:
            if resume_id:self.workspace._resume(db,owner,resume_id)
            rows=list(db.execute('''SELECT o.*,i.resume_id FROM rw_learning_observations o JOIN rw_interviews i USING(session_id)
                WHERE o.owner_id=? AND (? IS NULL OR i.resume_id=?) ORDER BY o.created_at DESC,o.observation_id LIMIT 2000''',(owner,resume_id,resume_id)))
            cache={};views=[]
            for row in rows:
                self._row(db,owner,row['observation_id'])
                view=self._view(db,owner,row,cache)
                if view['status']!='deleted':views.append(view)
            groups={}
            for view in views:
                if view['status']=='valid' and view['confirmed'] and not view['controls'].get('user_finding'):
                    groups.setdefault((view['payload']['condition_hash'],view['payload']['finding']),set()).add(view['session_id'])
            for view in views:
                if view['status']!='valid' or not view['confirmed'] or view['controls'].get('user_finding'):continue
                peers=groups[(view['payload']['condition_hash'],view['payload']['finding'])]
                view['consistent_distinct_sessions']=len(peers)
                if len(peers)>1:view['confidence']='repeated_consistent_observations'
            return views

    def materialize(self,owner,sid):
        with self.workspace._connection(write=True) as db:
            _,s,_=self.interviews._load(db,owner,sid)
            if s.status!='complete':raise WorkspaceConflict('learning_requires_completed_source')
            topics={t.anchor_id:t for t in s.plan};withdrawn=withdrawn_questions(db,owner,sid)
            if any(not usable_evaluation_source(s,t,topics[t.question.topic_id]) for t in s.turns if t.question.question_id not in withdrawn):
                raise WorkspaceConflict('learning_source_incomplete_semantic_review')
            payloads=[observation_payload(s,t,topics[t.question.topic_id],point) for t in s.turns if t.question.question_id not in withdrawn
                for point in ([t.question.focus_id] if t.question.focus_id in topics[t.question.topic_id].points else topics[t.question.topic_id].points)]
            if len(payloads)>100:raise WorkspaceConflict('learning_session_quota_reached')
            quota=db.execute('SELECT COUNT(*) FROM rw_learning_observations WHERE owner_id=?',(owner,)).fetchone()[0]
            added=0
            for data in payloads:
                fp=digest(data);key='learn-'+digest([owner,sid,data['question_id'],data['point_id'],fp])[:32]
                old_scope=db.execute('SELECT controls FROM rw_learning_observations WHERE owner_id=? AND session_id=? AND question_id=? AND point_id=?',
                    (owner,sid,data['question_id'],data['point_id'])).fetchall()
                if any(json.loads(old['controls']).get('deleted') for old in old_scope):continue
                if db.execute('SELECT 1 FROM rw_learning_observations WHERE observation_id=?',(key,)).fetchone():continue
                if quota+added>=2000:raise WorkspaceConflict('learning_owner_quota_reached')
                raw=encoded(data);controls=encoded({'confirmed':False,'paused':False,'deleted':False,'due_at':self.clock()})
                db.execute('INSERT INTO rw_learning_observations VALUES (?,?,?,?,?,?,?,?,?,?,0,?)',
                    (key,owner,sid,data['question_id'],data['point_id'],fp,raw,digest(raw),controls,digest(controls),self.clock()))
                added+=1
        return {'added':added,'source_session_id':sid,'observations':[v for v in self.list(owner) if v['session_id']==sid],
            'warning':'练习观察可纠正，不是用户能力画像、个人经历证明或已掌握结论。'}

    def preferences(self,owner,*,db=None):
        with (nullcontext(db) if db is not None else self.workspace._connection()) as db:
            row=db.execute('SELECT * FROM rw_learning_preferences WHERE owner_id=?',(owner,)).fetchone()
            if not row:return {'revision':0,'cadence_days':3,'daily_limit':10,'paused':False,'include_new':True,'source':'system_default'}
            if digest(row['payload'])!=row['payload_hash']:raise InvalidProvenance('learning_preferences_integrity_failed')
            return {'revision':row['revision'],**json.loads(row['payload']),'source':'explicit_user_preference'}

    def set_preferences(self,owner,request):
        with self.workspace._connection(write=True) as db:
            previous=self.preferences(owner,db=db)
            if previous['revision']!=request.expected_revision:raise WorkspaceConflict('learning_preferences_changed')
            raw=encoded(request.model_dump(exclude={'expected_revision'}))
            db.execute('INSERT OR REPLACE INTO rw_learning_preferences VALUES (?,?,?,?,?)',(owner,raw,digest(raw),request.expected_revision+1,self.clock()))
        return self.preferences(owner)

    def queue(self,owner,*,resume_id=None):
        preferences=self.preferences(owner);all_views=self.list(owner)
        if resume_id:
            with self.workspace._connection() as db:self.workspace._resume(db,owner,resume_id)
        views=[v for v in all_views if not resume_id or v['resume_id']==resume_id]
        day=int((self.clock()+8*3600)//DAY)
        with self.workspace._connection() as db:
            controls=[]
            for row in db.execute('SELECT controls,controls_hash FROM rw_learning_observations WHERE owner_id=?',(owner,)):
                if digest(row['controls'])!=row['controls_hash']:raise InvalidProvenance('learning_record_integrity_failed')
                controls.append(json.loads(row['controls']))
        reviewed_today=sum(bool(v.get('last_reviewed_at')) and int((v['last_reviewed_at']+8*3600)//DAY)==day for v in controls)
        remaining=max(0,preferences['daily_limit']-reviewed_today)
        eligible=[v for v in views if v['queue_bucket']=='review_due' or (v['queue_bucket']=='new' and preferences['include_new'])]
        eligible.sort(key=lambda v:(v['queue_bucket']=='new',v['controls'].get('due_at',0),v['observation_id']))
        return {'preferences':preferences,'items':[] if preferences['paused'] else eligible[:remaining],
            'reviewed_today':reviewed_today,'remaining_today':remaining,'day_timezone':'Asia/Shanghai',
            'counts':{key:sum(v['queue_bucket']==key for v in views) for key in ('new','review_due','reviewed','paused','historical_version','expired','excluded')},
            'rule_version':'s7-review-rules-1','warning':'按用户核对与时间生成建议；标已复核不代表已经掌握。'}

    def _operation(self,db,row,request):
        old=db.execute('SELECT * FROM rw_learning_operations WHERE observation_id=? AND request_key=?',(row['observation_id'],request.request_key)).fetchone()
        if old:
            if old['request_hash']!=digest(request.model_dump()):raise WorkspaceConflict('learning_request_key_conflict')
            return old
        if row['revision']!=request.expected_revision:raise WorkspaceConflict('learning_revision_changed')
        return None

    def _save_control(self,db,row,request,controls,*,result_id=None):
        raw=encoded(controls)
        db.execute('UPDATE rw_learning_observations SET controls=?,controls_hash=?,revision=revision+1 WHERE observation_id=?',
            (raw,digest(raw),row['observation_id']))
        db.execute('INSERT INTO rw_learning_operations VALUES (?,?,?,?)',
            (row['observation_id'],request.request_key,digest(request.model_dump()),result_id))

    def act(self,owner,key,request):
        with self.workspace._connection(write=True) as db:
            row=self._row(db,owner,key)
            if self._operation(db,row,request):return self._view(db,owner,row,{})
            controls=json.loads(row['controls']);view=self._view(db,owner,row,{})
            if controls.get('deleted'):raise WorkspaceNotFound('learning_observation_deleted')
            if request.action not in ('delete','pause') and view['status'] in ('invalid','withdrawn'):raise WorkspaceConflict('learning_source_not_eligible')
            now=self.clock()
            if request.action in ('confirm','correct'):
                controls.update(confirmed=True,checked_at=now)
                if request.action=='correct':controls.update(user_finding=request.user_finding,user_note=request.note,correction_source='explicit_user')
            elif request.action in ('pause','resume'):controls['paused']=request.action=='pause'
            elif request.action=='schedule':controls['due_at']=now+request.review_in_days*DAY
            elif request.action=='mark_reviewed':
                if not controls.get('confirmed'):raise WorkspaceConflict('learning_confirmation_required')
                controls.update(last_reviewed_at=now,checked_at=now,due_at=now+self.preferences(owner,db=db)['cadence_days']*DAY)
            elif request.action=='withdraw':
                db.execute('INSERT OR IGNORE INTO rw_learning_withdrawals VALUES (?,?,?,?,?)',(row['session_id'],row['question_id'],owner,request.note,now))
            elif request.action=='delete':
                controls={'deleted':True}
                db.execute('UPDATE rw_learning_observations SET payload=NULL,payload_hash=NULL WHERE observation_id=?',(key,))
            self._save_control(db,row,request,controls)
        return self.get(owner,key)

    def practice_context(self,db,owner,request):
        row=self._row(db,owner,request.learning_observation_id);view=self._view(db,owner,row,{})
        if view['status']!='valid' or not view['confirmed'] or view['paused']:raise WorkspaceConflict('learning_source_not_eligible')
        if view['historical_version'] and not request.learning_allow_historical_version:raise WorkspaceConflict('learning_historical_version_requires_confirmation')
        s,_=self._source(db,owner,row['session_id'],{})
        if (request.prior_session_id,request.version_id,request.expected_content_hash,request.jd_text,request.project_id,request.snapshot_id)!=(s.session_id,s.version_id,s.version_hash,s.jd_text,s.project_id,s.snapshot_id):
            raise WorkspaceConflict('learning_practice_scope_changed')
        turn=next(t for t in s.turns if t.question.question_id==row['question_id'])
        topic=next(t for t in s.plan if t.anchor_id==turn.question.topic_id)
        return topic.model_copy(deep=True,update={'prompt':turn.question.prompt,'references':turn.question.references}),turn.question,view['payload']['condition_hash']

    def practice(self,owner,key,request,engine):
        from job_agent.resume_workspace.interview_contracts import InterviewStart
        with self.workspace._connection(write=True) as db:
            row=self._row(db,owner,key);old=self._operation(db,row,request)
            if old:return old['result_id']
            view=self._view(db,owner,row,{})
            if view['status']!='valid' or not view['confirmed'] or view['paused']:raise WorkspaceConflict('learning_source_not_eligible')
            if view['historical_version'] and not request.allow_historical_version:raise WorkspaceConflict('learning_historical_version_requires_confirmation')
            s,_=self._source(db,owner,row['session_id'],{})
            start=InterviewStart(request_key='learning-'+digest([key,request.request_key])[:40],version_id=s.version_id,
                expected_content_hash=s.version_hash,jd_text=s.jd_text,mode=request.mode,max_turns=2,use_retrieval=True,
                track='weakness',prior_session_id=s.session_id,project_id=s.project_id,snapshot_id=s.snapshot_id,
                learning_observation_id=key,allow_external_processing=request.allow_external_processing,
                learning_allow_historical_version=request.allow_historical_version)
            sid=self.interviews.start(owner,s.resume_id,start,engine,db=db)
            controls=json.loads(row['controls']);controls['last_practice_session_id']=sid
            self._save_control(db,row,request,controls,result_id=sid)
            return sid

    def comparison(self,owner,sid):
        with self.workspace._connection() as db:
            _,s,_=self.interviews._load(db,owner,sid)
            if not s.learning_observation_id:return None
            try:old=self._view(db,owner,self._row(db,owner,s.learning_observation_id),{})
            except WorkspaceNotFound:old={'status':'invalid','controls':{},'payload':None}
            if s.status!='complete':raise WorkspaceConflict('learning_comparison_requires_completion')
            matches=[]
            if old['status']=='valid':
                topics={t.anchor_id:t for t in s.plan};pid=old['payload']['point_id']
                for turn in s.turns:
                    topic=topics[turn.question.topic_id]
                    if pid in topic.points:
                        new=observation_payload(s,turn,topic,pid)
                        if new['condition_hash']==old['payload']['condition_hash']:matches.append(new)
            comparable=bool(matches) and not old.get('controls',{}).get('user_finding')
            return {'source_observation_id':s.learning_observation_id,'status':'same_recorded_conditions' if comparable else 'not_comparable',
                'before_finding':old['payload']['finding'] if comparable else None,'after_finding':matches[-1]['finding'] if comparable else None,
                'mastery_claim':None,'warning':'仅比较同记录条件下的参考评价，不计算能力提升；用户纠正/撤回或条件变化时不直接比较。'}

"""Owner-scoped version/JD interview snapshots; private rubric never in active view."""
from datetime import datetime, UTC
from time import time
from uuid import uuid4
from contextlib import nullcontext

from job_agent.resume_workspace.interview_contracts import (
    InterviewState, InterviewView, PublicQuestion, PublicTurn, PendingAnswer, InterviewStart,
)
from job_agent.resume_workspace.interview_collaboration import build_plan, question_for
from job_agent.resume_workspace.match_repository import MatchRepository
from job_agent.resume_workspace.matching import digest
from job_agent.resume_workspace.repository import WorkspaceConflict, WorkspaceNotFound, InvalidProvenance
from job_agent.resume_workspace.execution_state import sync_interview,interview_identity

DDL='''
CREATE TABLE IF NOT EXISTS rw_interviews(
 session_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL,
 resume_id TEXT NOT NULL REFERENCES rw_resumes(resume_id) ON DELETE CASCADE,
 version_id TEXT NOT NULL REFERENCES rw_versions(version_id) ON DELETE CASCADE,
 request_key TEXT NOT NULL, request_hash TEXT NOT NULL,
 state_json TEXT NOT NULL,state_hash TEXT NOT NULL,
 execution_token TEXT,lease_until REAL NOT NULL DEFAULT 0,
 UNIQUE(owner_id,request_key)
);
CREATE INDEX IF NOT EXISTS rw_interviews_resume ON rw_interviews(owner_id,resume_id);
CREATE TABLE IF NOT EXISTS rw_interview_answers(
 session_id TEXT NOT NULL REFERENCES rw_interviews(session_id) ON DELETE CASCADE,
 request_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL,
 PRIMARY KEY(session_id,request_key)
);
'''


class InterviewRepository:
    def __init__(self,workspace,*,code=None,public=None):
        self.workspace=workspace
        self.matches=MatchRepository(workspace)
        with workspace._connection() as db:db.executescript(DDL)
        from job_agent.resume_workspace.code_rag import CodeRAGService
        from job_agent.resume_workspace.public_knowledge import PublicKnowledgeService
        self.code=code or CodeRAGService(workspace);self.public=public or PublicKnowledgeService(workspace)

    def start(self,owner,resume_id,request,engine,*,db=None):
        hashed=digest(resume_id+request.stable_json())
        if request.match_id:
            match=self.matches.get(owner,request.match_id)
            if match.resume_id!=resume_id or match.jd_text!=request.jd_text:raise WorkspaceConflict('interview_match_snapshot_mismatch')
        with (nullcontext(db) if db is not None else self.workspace._connection(write=True)) as db:
            self.workspace._resume(db,owner,resume_id)
            version=self.workspace._version(db,resume_id,request.version_id)
            self.workspace._validate_document(db,owner,version.document)
            if version.content_hash!=request.expected_content_hash:raise WorkspaceConflict('interview_version_changed')
            old=db.execute('SELECT * FROM rw_interviews WHERE owner_id=? AND request_key=?',(owner,request.request_key)).fetchone()
            if old:
                if old['request_hash']!=hashed:raise WorkspaceConflict('interview_request_key_conflict')
                return old['session_id']
            sid='interview-'+uuid4().hex
            learning_context=None
            if request.learning_observation_id:
                if not getattr(self,'learning',None):raise WorkspaceConflict('learning_practice_not_configured')
                learning_context=self.learning.practice_context(db,owner,request)
            state=InterviewState(session_id=sid,resume_id=resume_id,version_id=version.version_id,version_hash=version.content_hash,
                jd_text=request.jd_text,match_id=request.match_id,mode=request.mode,
                provider=getattr(engine.provider,'provider_name','unknown') if request.mode=='llm' else 'local-rules',
                model=getattr(engine.provider,'model','unknown') if request.mode=='llm' else 'question-bank-adapter-v1',
                created_at=datetime.now(UTC),max_turns=request.max_turns,plan=build_plan(request.jd_text),current=None)
            if learning_context:
                state.learning_observation_id=request.learning_observation_id
                state.learning_allow_historical_version=request.learning_allow_historical_version
                state.learning_condition_hash=learning_context[2]
            if request.use_retrieval:
                if not hasattr(engine,'prepare'):raise WorkspaceConflict('retrieval_interview_not_configured')
                if learning_context:engine.prepare(owner,state,request,self,learning_context=learning_context)
                else:engine.prepare(owner,state,request,self)
            state.current=question_for(state)
            if learning_context:state.current=learning_context[1].model_copy(deep=True,update={'question_id':sid+'-q1'})
            sync_interview(state,owner)
            raw=state.model_dump_json()
            db.execute('INSERT INTO rw_interviews(session_id,owner_id,resume_id,version_id,request_key,request_hash,state_json,state_hash) VALUES(?,?,?,?,?,?,?,?)',
                (sid,owner,resume_id,version.version_id,request.request_key,hashed,raw,digest(raw)))
            return sid

    def _load(self,db,owner,sid):
        row=db.execute('SELECT * FROM rw_interviews WHERE session_id=? AND owner_id=?',(sid,owner)).fetchone()
        if row is None:raise WorkspaceNotFound('interview_not_found')
        if digest(row['state_json'])!=row['state_hash']:raise InvalidProvenance('interview_integrity_failed')
        s=InterviewState.model_validate_json(row['state_json'])
        version=self.workspace._version(db,row['resume_id'],row['version_id'])
        self.workspace._validate_document(db,owner,version.document)
        if s.session_id!=sid or s.resume_id!=row['resume_id'] or s.version_id!=version.version_id or s.version_hash!=version.content_hash or s.revision!=len(s.turns):
            raise InvalidProvenance('interview_integrity_failed')
        original=InterviewStart(request_key='integrity-check',version_id=s.version_id,expected_content_hash=s.version_hash,
            jd_text=s.jd_text,match_id=s.match_id,mode=s.mode,max_turns=s.max_turns,use_retrieval=s.use_retrieval,
            track=s.track,project_id=s.project_id,snapshot_id=s.snapshot_id,prior_session_id=s.prior_session_id,
            learning_observation_id=s.learning_observation_id,learning_allow_historical_version=s.learning_allow_historical_version)
        if digest(s.resume_id+original.stable_json())!=row['request_hash']:
            raise InvalidProvenance('interview_request_integrity_failed')
        if s.execution:
            try:s.execution.validate_binding(owner,sid,interview_identity(s))
            except ValueError as exc:raise InvalidProvenance('interview_execution_integrity_failed') from exc
            if s.execution.revision!=s.revision:raise InvalidProvenance('interview_execution_revision_changed')
        if s.use_retrieval:
            if s.bound_owner!=owner:raise InvalidProvenance('interview_reference_scope_changed')
            refs=[r for t in s.plan for r in t.references]+[r for t in s.turns for r in t.question.references]
            for pack in s.evidence_packs:
                scope=pack.plan.scope
                if scope.kind=='private_project' and (scope.owner_id!=owner or scope.project_id!=s.project_id or scope.snapshot_id!=s.snapshot_id):
                    raise InvalidProvenance('interview_evidence_pack_scope_changed')
                for item in pack.items:
                    ref=item.reference
                    if scope.kind=='private_project' and ref.scope!='private_project':raise InvalidProvenance('interview_evidence_pack_scope_changed')
                    if scope.kind!='private_project' and (ref.scope!='public_knowledge' or scope.public_versions.get(ref.source_id)!=ref.snapshot_id):
                        raise InvalidProvenance('interview_evidence_pack_scope_changed')
                    refs.append(ref)
            if s.current:refs+=s.current.references
            seen=set()
            for ref in refs:
                reference_key=ref.model_dump_json()
                if reference_key in seen:continue
                seen.add(reference_key)
                if ref.scope=='private_project':
                    if ref.project_id!=s.project_id or ref.snapshot_id!=s.snapshot_id:raise InvalidProvenance('interview_reference_scope_changed')
                    self.code.validate_reference(owner,ref,db=self.code.citation_connection(db,self.workspace))
                elif ref.scope=='public_knowledge':self.public.repository.validate_reference(ref,db=db)
                else:raise InvalidProvenance('interview_reference_scope_changed')
        return row,s,version

    def get(self,owner,sid):
        with self.workspace._connection() as db:
            row,s,_=self._load(db,owner,sid)
            head=self.workspace._resume(db,owner,s.resume_id)['head_version_id']
            # Explicit projection. No state.model_dump in the live API.
            def public(q):return PublicQuestion(**{k:getattr(q,k) for k in PublicQuestion.model_fields}) if q else None
            return InterviewView(session_id=sid,resume_id=s.resume_id,version_id=s.version_id,version_hash=s.version_hash,
                jd_text=s.jd_text,match_id=s.match_id,mode=s.mode,provider=s.provider,model=s.model,status=s.status,revision=s.revision,max_turns=s.max_turns,
                created_at=s.created_at,current=public(s.current),turns=[PublicTurn(question=public(t.question),answer=t.answer) for t in s.turns],
                messages=s.messages,usage=s.usage,answer_pending=s.pending is not None,
                track=s.track,use_retrieval=s.use_retrieval,project_id=s.project_id,snapshot_id=s.snapshot_id,tool_trace=s.tool_trace,tool_calls=s.tool_calls,
                resumable=s.pending is not None and not s.model_inflight and s.status=='active' and
                    (not row['execution_token'] or row['lease_until']<=time()),model_inflight=s.model_inflight,error_code=s.error_code,
                version_is_current=head==s.version_id,warnings=[
                    '题库技术练习，不代表真实面试表现或录用概率；本地仅按词面线索评估。',
                    '绑定本次简历版本/JD，之后编辑不会改变本场；C1 自述未独立核实，缺少材料不等于没有能力。',
                    '进行中隐藏参考要点与详细评价，结束后复盘；本次不会写简历或投递。'])

    def list(self,owner,resume_id):
        with self.workspace._connection() as db:
            self.workspace._resume(db,owner,resume_id)
            rows=db.execute('SELECT session_id FROM rw_interviews WHERE owner_id=? AND resume_id=? ORDER BY rowid DESC LIMIT 100',(owner,resume_id)).fetchall()
            return [{'session_id':sid,'version_id':s.version_id,'status':s.status,'revision':s.revision,'created_at':s.created_at}
                    for sid,s in [(row['session_id'],self._load(db,owner,row['session_id'])[1]) for row in rows]]

    def answer(self,owner,sid,request):
        hashed=digest(request.model_dump_json(exclude={'allow_external_processing','request_key'}))
        with self.workspace._connection(write=True) as db:
            row,s,_=self._load(db,owner,sid)
            old=db.execute('SELECT * FROM rw_interview_answers WHERE session_id=? AND request_key=?',(sid,request.request_key)).fetchone()
            if old:
                if old['request_hash']!=hashed:raise WorkspaceConflict('interview_answer_key_conflict')
                return False # Never re-dispatch a saved answer automatically.
            if s.status!='active' or s.pending is not None:raise WorkspaceConflict('interview_not_ready')
            if s.revision!=request.expected_revision or s.current.question_id!=request.question_id:raise WorkspaceConflict('interview_question_changed')
            s.pending=PendingAnswer(request_key=request.request_key,answer=request.answer);s.next_node='evaluator'
            sync_interview(s,owner)
            raw=s.model_dump_json()
            db.execute('UPDATE rw_interviews SET state_json=?,state_hash=? WHERE session_id=?',(raw,digest(raw),sid))
            db.execute('INSERT INTO rw_interview_answers VALUES(?,?,?,?)',(sid,request.request_key,hashed,'pending'))
            return True

    def claim(self,owner,sid):
        with self.workspace._connection(write=True) as db:
            row,s,v=self._load(db,owner,sid)
            if row['execution_token'] and row['lease_until']>time():raise WorkspaceConflict('interview_in_progress')
            if s.model_inflight:raise WorkspaceConflict('interview_uncertain_model_call')
            if s.status!='active' or not s.pending:raise WorkspaceConflict('interview_not_resumable')
            token=uuid4().hex
            execution=sync_interview(s,owner)
            if execution.execution_token is not None:execution.attempt+=1
            execution.execution_token=token;execution.lease_until=time()+600
            db.execute('UPDATE rw_interviews SET execution_token=?,lease_until=? WHERE session_id=?',(token,time()+600,sid))
            return token,s,v

    def checkpoint(self,owner,sid,token,state):
        sync_interview(state,owner)
        raw=state.model_dump_json()
        with self.workspace._connection(write=True) as db:
            row,previous,_=self._load(db,owner,sid)
            if row['execution_token']!=token:raise WorkspaceConflict('interview_execution_changed')
            db.execute('UPDATE rw_interviews SET state_json=?,state_hash=?,lease_until=? WHERE session_id=?',(raw,digest(raw),time()+600,sid))
            if previous.pending and state.pending is None:
                db.execute("UPDATE rw_interview_answers SET status='complete' WHERE session_id=? AND request_key=?",(sid,previous.pending.request_key))

    def release(self,owner,sid,token):
        with self.workspace._connection(write=True) as db:db.execute('UPDATE rw_interviews SET execution_token=NULL,lease_until=0 WHERE session_id=? AND owner_id=? AND execution_token=?',(sid,owner,token))

    def finish(self,owner,sid,revision):
        with self.workspace._connection(write=True) as db:
            row,s,_=self._load(db,owner,sid)
            if s.status=='complete':return
            if s.revision!=revision:raise WorkspaceConflict('interview_question_changed')
            if s.pending or s.model_inflight or row['execution_token']:raise WorkspaceConflict('interview_in_progress')
            s.status='complete';s.current=None
            sync_interview(s,owner)
            raw=s.model_dump_json();db.execute('UPDATE rw_interviews SET state_json=?,state_hash=? WHERE session_id=?',(raw,digest(raw),sid))

    def set_paused(self,owner,sid,revision,paused):
        with self.workspace._connection(write=True) as db:
            row,s,_=self._load(db,owner,sid)
            if s.revision!=revision:raise WorkspaceConflict('interview_question_changed')
            if s.pending or s.model_inflight or row['execution_token']:raise WorkspaceConflict('interview_in_progress')
            if s.status not in ('active','paused'):raise WorkspaceConflict('interview_already_terminal')
            s.status='paused' if paused else 'active'
            sync_interview(s,owner)
            raw=s.model_dump_json();db.execute('UPDATE rw_interviews SET state_json=?,state_hash=? WHERE session_id=?',(raw,digest(raw),sid))

    def review(self,owner,sid):
        with self.workspace._connection() as db:
            _,s,_=self._load(db,owner,sid)
            if s.status!='complete':raise WorkspaceConflict('interview_review_not_available')
            topics={t.anchor_id:t for t in s.plan}
            from job_agent.resume_workspace.learning import withdrawn_questions
            withdrawn=withdrawn_questions(db,owner,sid)
            comparison=None
            if s.prior_session_id:
                try:_,previous,_=self._load(db,owner,s.prior_session_id)
                except (WorkspaceNotFound,WorkspaceConflict,InvalidProvenance):previous=None
                prior_withdrawn=withdrawn_questions(db,owner,s.prior_session_id)
                old_topics={t.anchor_id:t for t in previous.plan} if previous else {}
                old_turns={t.question.topic_id:t for t in previous.turns} if previous else {}
                new_turns={t.question.topic_id:t for t in s.turns}
                same_model=previous and (s.mode,s.provider,s.model,s.version_hash,s.jd_text)==(previous.mode,previous.provider,previous.model,previous.version_hash,previous.jd_text)
                comparable=[k for k in new_turns if k in old_turns and same_model and
                    new_turns[k].question.question_id not in withdrawn and old_turns[k].question.question_id not in prior_withdrawn and
                    topics[k].points==old_topics[k].points and topics[k].aliases==old_topics[k].aliases and
                    new_turns[k].question.prompt==old_turns[k].question.prompt and
                    new_turns[k].question.focus_id==old_turns[k].question.focus_id and
                    [(r.snapshot_id,r.path,r.start_line,r.end_line,r.content_hash) for r in new_turns[k].question.references]==
                    [(r.snapshot_id,r.path,r.start_line,r.end_line,r.content_hash) for r in old_turns[k].question.references] and
                    (new_turns[k].evaluation.method_version,new_turns[k].evaluation.assessment_mode)==
                    (old_turns[k].evaluation.method_version,old_turns[k].evaluation.assessment_mode)]
                comparison={'prior_session_id':s.prior_session_id,'basis':'last answered turn per identical question/references/rubric/aliases/model/evaluation method; reference only',
                    'status':'comparable' if comparable else 'not_comparable','topics':[
                        {'topic_id':k,'before_covered':len(old_turns[k].evaluation.covered_ids),
                         'after_covered':len(new_turns[k].evaluation.covered_ids),'total':len(topics[k].points)} for k in comparable],
                    'warning':'题目或评价条件不一致时不计算提升；词面要点变化不能证明能力或真实教学效果。'}
            return {'session_id':sid,'scope':'规则参考' if s.mode=='local_demo' else '模型参考，非真实性证明',
                'practice_comparison':comparison,
                'track':s.track,'source_boundary':'通用知识/源码实现/个人贡献分别判断；源码存在和测试文件不代表已运行或本人完成。',
                'weaknesses':[{'topic_id':t.question.topic_id,'question':t.question.prompt,'missing':t.evaluation.missing_ids} for t in s.turns if t.evaluation.missing_ids and t.question.question_id not in withdrawn],
                'code_references':[r.model_dump(mode='json') for t in s.turns for r in t.question.references if r.scope=='private_project'],
                'turns':[{'question_id':t.question.question_id,'question':t.question.prompt,'answer':t.answer,'assessment_withdrawn':t.question.question_id in withdrawn,
                    'covered':[topics[t.question.topic_id].points[k] for k in t.evaluation.covered_ids],
                    'missing':[topics[t.question.topic_id].points[k] for k in t.evaluation.missing_ids],
                    'claim_needs_evidence':t.evaluation.claim_needs_evidence,'note':t.evaluation.note,'decision':t.decision.action} for t in s.turns],
                'assessment_details':[{'question_id':t.question.question_id,'mode':t.evaluation.assessment_mode,
                    'method_version':t.evaluation.method_version,'semantic_assessments_present':bool(t.evaluation.point_assessments),
                    'points':[a.model_dump() for a in t.evaluation.point_assessments]} for t in s.turns],
                'warning':'未覆盖可能是表达或规则识别问题，不代表没有能力；个人经历需补充材料，当前未独立核实。'}

"""Owner-scoped job timeline and immutable project snapshots on the product DB."""
from __future__ import annotations
from contextlib import nullcontext
from datetime import datetime,UTC
from hashlib import sha256
import json
from typing import Literal
from uuid import uuid4
from pydantic import Field
from fastapi import Depends,Query,Request,Response
from job_agent.schemas import StrictModel
from job_agent.resume_workspace.repository import WorkspaceConflict,WorkspaceNotFound
from job_agent.resume_workspace.project_import import scan_zip,checked_path,excluded,MAX_FILE_BYTES
from job_agent.resume_workspace.github_import import GitHubImport,PublicGitHubImporter


def now():return datetime.now(UTC).isoformat()
def encoded(value):return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'))
def digest(value):return sha256(encoded(value).encode()).hexdigest()
Stage=Literal['saved','applied','screening','interview','offer','rejected','withdrawn']


class JobCreate(StrictModel):
    request_key: str=Field(pattern=r'^[a-zA-Z0-9_-]{8,80}$')
    company: str=Field(min_length=1,max_length=120)
    title: str=Field(min_length=1,max_length=120)
    jd_text: str=Field(min_length=1,max_length=12000)
    url: str=Field(default='',max_length=1000)
    notes: str=Field(default='',max_length=5000)


class JobUpdate(StrictModel):
    request_key: str=Field(pattern=r'^[a-zA-Z0-9_-]{8,80}$')
    expected_revision: int=Field(ge=1)
    stage: Stage
    note: str=Field(default='',max_length=3000)


class JobLink(StrictModel):
    resume_id: str
    version_id: str
    interview_id: str|None=None


class ProjectCreate(StrictModel):
    name: str=Field(min_length=1,max_length=120)
    contribution: str=Field(default='',max_length=6000)
    description: str=Field(default='',max_length=6000)
    license_note: str=Field(default='私人材料，仅本用户空间使用',max_length=1000)


class ProjectDocument(StrictModel):
    path: str=Field(min_length=1,max_length=200)
    text: str=Field(min_length=1,max_length=100000)


_DDL='''
CREATE TABLE IF NOT EXISTS v3_jobs (
    job_id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,request_key TEXT NOT NULL,
    request_hash TEXT NOT NULL,payload TEXT NOT NULL,stage TEXT NOT NULL,
    revision INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
    UNIQUE(owner_id,request_key));
CREATE INDEX IF NOT EXISTS v3_job_owner ON v3_jobs(owner_id);
CREATE TABLE IF NOT EXISTS v3_job_events (
    event_id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES v3_jobs(job_id) ON DELETE CASCADE,
    request_key TEXT NOT NULL,request_hash TEXT NOT NULL,stage TEXT NOT NULL,note TEXT NOT NULL,
    revision INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(job_id,request_key));
CREATE TABLE IF NOT EXISTS v3_job_links (
    job_id TEXT NOT NULL REFERENCES v3_jobs(job_id) ON DELETE CASCADE,
    version_id TEXT NOT NULL REFERENCES rw_versions(version_id) ON DELETE CASCADE,
    interview_id TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,
    PRIMARY KEY(job_id,version_id,interview_id));
CREATE TABLE IF NOT EXISTS v3_projects (
    project_id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,payload TEXT NOT NULL,
    created_at TEXT NOT NULL,current_snapshot TEXT,index_status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS v3_project_owner ON v3_projects(owner_id);
CREATE TABLE IF NOT EXISTS v3_project_snapshots (
    snapshot_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES v3_projects(project_id) ON DELETE CASCADE,
    content_hash TEXT NOT NULL,origin TEXT NOT NULL,commit_sha TEXT,metadata TEXT NOT NULL,
    created_at TEXT NOT NULL,UNIQUE(project_id,content_hash));
CREATE TABLE IF NOT EXISTS v3_project_files (
    snapshot_id TEXT NOT NULL REFERENCES v3_project_snapshots(snapshot_id) ON DELETE CASCADE,
    path TEXT NOT NULL,content_hash TEXT NOT NULL,text TEXT NOT NULL,
    PRIMARY KEY(snapshot_id,path));
'''


class LongTermRepository:
    def __init__(self,workspace):
        self.workspace=workspace
        with workspace._connection(write=True) as db:db.executescript(_DDL)

    @staticmethod
    def _job(db,owner,job_id):
        row=db.execute('SELECT * FROM v3_jobs WHERE job_id=? AND owner_id=?',(job_id,owner)).fetchone()
        if row is None:raise WorkspaceNotFound('job_not_found')
        return row

    def create_job(self,owner,request:JobCreate):
        request=JobCreate.model_validate(request.model_dump());h=digest(request.model_dump(exclude={'request_key'}))
        with self.workspace._connection(write=True) as db:
            row=db.execute('SELECT * FROM v3_jobs WHERE owner_id=? AND request_key=?',(owner,request.request_key)).fetchone()
            if row:
                if row['request_hash']!=h:raise WorkspaceConflict('job_request_key_conflict')
                key=row['job_id']
            else:
                if db.execute('SELECT COUNT(*) FROM v3_jobs WHERE owner_id=?',(owner,)).fetchone()[0]>=200:raise WorkspaceConflict('job_quota_reached')
                key='job-'+uuid4().hex;t=now()
                db.execute('INSERT INTO v3_jobs VALUES (?,?,?,?,?,?,?,?,?)',(key,owner,request.request_key,h,encoded(request.model_dump(exclude={'request_key'})),'saved',1,t,t))
                db.execute('INSERT INTO v3_job_events VALUES (?,?,?,?,?,?,?,?)',('event-'+uuid4().hex,key,request.request_key,h,'saved','创建岗位',1,t))
        return self.get_job(owner,key)

    def get_job(self,owner,job_id):
        with self.workspace._connection() as db:
            row=self._job(db,owner,job_id)
            return {**json.loads(row['payload']),'job_id':job_id,'stage':row['stage'],'revision':row['revision'],
                'created_at':row['created_at'],'updated_at':row['updated_at'],
                'events':[dict(x) for x in db.execute('SELECT event_id,stage,note,revision,created_at FROM v3_job_events WHERE job_id=? ORDER BY revision',(job_id,))],
                'links':[dict(x) for x in db.execute('''SELECT l.version_id,l.interview_id,l.created_at,v.resume_id,v.sequence,v.content_hash
                    FROM v3_job_links l JOIN rw_versions v ON v.version_id=l.version_id WHERE l.job_id=? ORDER BY l.created_at''',(job_id,))]}

    def list_jobs(self,owner):
        with self.workspace._connection() as db:ids=[r[0] for r in db.execute('SELECT job_id FROM v3_jobs WHERE owner_id=? ORDER BY updated_at DESC LIMIT 200',(owner,))]
        return [self.get_job(owner,key) for key in ids]

    def update_job(self,owner,key,request:JobUpdate):
        h=digest(request.model_dump())
        with self.workspace._connection(write=True) as db:
            row=self._job(db,owner,key)
            old=db.execute('SELECT request_hash FROM v3_job_events WHERE job_id=? AND request_key=?',(key,request.request_key)).fetchone()
            if old:
                if old[0]!=h:raise WorkspaceConflict('job_request_key_conflict')
            else:
                if row['revision']!=request.expected_revision:raise WorkspaceConflict('job_revision_changed')
                t=now();revision=row['revision']+1
                db.execute('INSERT INTO v3_job_events VALUES (?,?,?,?,?,?,?,?)',('event-'+uuid4().hex,key,request.request_key,h,request.stage,request.note,revision,t))
                db.execute('UPDATE v3_jobs SET stage=?,revision=?,updated_at=? WHERE job_id=?',(request.stage,revision,t,key))
        return self.get_job(owner,key)

    def link_job(self,owner,key,request:JobLink):
        with self.workspace._connection(write=True) as db:
            self._job(db,owner,key);self.workspace._resume(db,owner,request.resume_id)
            version=self.workspace._version(db,request.resume_id,request.version_id)
            self.workspace._validate_document(db,owner,version.document)
            if request.interview_id:
                if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='rw_interviews'").fetchone():raise WorkspaceNotFound('interview_not_found')
                row=db.execute('SELECT owner_id,resume_id,version_id FROM rw_interviews WHERE session_id=?',(request.interview_id,)).fetchone()
                if row is None or row['owner_id']!=owner or row['resume_id']!=request.resume_id:raise WorkspaceNotFound('interview_not_found')
                if row['version_id']!=request.version_id:raise WorkspaceConflict('job_interview_version_mismatch')
            db.execute('INSERT OR IGNORE INTO v3_job_links VALUES (?,?,?,?)',(key,request.version_id,request.interview_id or '',now()))
        return self.get_job(owner,key)

    def delete_job(self,owner,key):
        with self.workspace._connection(write=True) as db:self._job(db,owner,key);db.execute('DELETE FROM v3_jobs WHERE job_id=?',(key,))

    @staticmethod
    def _project(db,owner,key):
        row=db.execute('SELECT * FROM v3_projects WHERE project_id=? AND owner_id=?',(key,owner)).fetchone()
        if row is None:raise WorkspaceNotFound('project_not_found')
        return row

    def create_project(self,owner,request:ProjectCreate):
        with self.workspace._connection(write=True) as db:
            if db.execute('SELECT COUNT(*) FROM v3_projects WHERE owner_id=?',(owner,)).fetchone()[0]>=20:raise WorkspaceConflict('project_quota_reached')
            key='project-'+uuid4().hex
            db.execute('INSERT INTO v3_projects VALUES (?,?,?,?,?,?)',(key,owner,encoded(request.model_dump()),now(),None,'not_imported'))
        return self.get_project(owner,key)

    def get_project(self,owner,key):
        with self.workspace._connection() as db:
            row=self._project(db,owner,key)
            snapshots=[{**{k:s[k] for k in ('snapshot_id','content_hash','origin','commit_sha','created_at')},'metadata':json.loads(s['metadata'])} for s in db.execute('SELECT * FROM v3_project_snapshots WHERE project_id=? ORDER BY created_at DESC',(key,))]
            return {**json.loads(row['payload']),'project_id':key,'created_at':row['created_at'],'current_snapshot':row['current_snapshot'],
                'index_status':row['index_status'],'contribution_status':'self_attested_not_verified','snapshots':snapshots}

    def list_projects(self,owner):
        with self.workspace._connection() as db:ids=[r[0] for r in db.execute('SELECT project_id FROM v3_projects WHERE owner_id=? ORDER BY created_at DESC LIMIT 20',(owner,))]
        return [self.get_project(owner,key) for key in ids]

    def publish_files(self,owner,key,files,*,origin,commit_sha=None,metadata=None):
        if not files or len(files)>1200 or sum(len(text.encode()) for text in files.values())>24*1024*1024:raise WorkspaceConflict('project_content_limit')
        for path,text in files.items():
            checked_path(path)
            if len(text.encode())>MAX_FILE_BYTES or excluded(path,text):raise WorkspaceConflict('project_file_rejected')
        manifest={p:sha256(text.encode()).hexdigest() for p,text in sorted(files.items())}
        content_hash=digest({'files':manifest,'origin':origin,'commit_sha':commit_sha})
        with self.workspace._connection(write=True) as db:
            self._project(db,owner,key)
            row=db.execute('SELECT snapshot_id FROM v3_project_snapshots WHERE project_id=? AND content_hash=?',(key,content_hash)).fetchone()
            if row:snapshot=row[0]
            else:
                stored_bytes=db.execute('''SELECT COALESCE(SUM(length(CAST(f.text AS BLOB))),0) FROM v3_project_files f
                    JOIN v3_project_snapshots s ON s.snapshot_id=f.snapshot_id JOIN v3_projects p ON p.project_id=s.project_id
                    WHERE p.owner_id=?''',(owner,)).fetchone()[0]
                if stored_bytes+sum(len(t.encode()) for t in files.values())>100*1024*1024:raise WorkspaceConflict('project_storage_quota_reached')
                count=db.execute('SELECT COUNT(*) FROM v3_project_snapshots WHERE project_id=?',(key,)).fetchone()[0]
                if count>=10:raise WorkspaceConflict('project_snapshot_quota_reached')
                snapshot='snapshot-'+uuid4().hex
                db.execute('INSERT INTO v3_project_snapshots VALUES (?,?,?,?,?,?,?)',(snapshot,key,content_hash,origin,commit_sha,encoded(metadata or {}),now()))
                db.executemany('INSERT INTO v3_project_files VALUES (?,?,?,?)',[(snapshot,p,manifest[p],text) for p,text in sorted(files.items())])
            db.execute('UPDATE v3_projects SET current_snapshot=?,index_status=? WHERE project_id=?',(snapshot,'pending_index',key))
        return self.get_project(owner,key)

    def import_zip(self,owner,key,data):
        self.get_project(owner,key)
        files,metadata=scan_zip(data)
        return self.publish_files(owner,key,files,origin='zip',metadata=metadata)

    def add_document(self,owner,key,request:ProjectDocument):
        path=checked_path(request.path)
        if not path.casefold().endswith(('.md','.txt')):raise WorkspaceConflict('project_document_type')
        project=self.get_project(owner,key)
        files=self.files(owner,key,project['current_snapshot']) if project['current_snapshot'] else {}
        files[path]=request.text
        return self.publish_files(owner,key,files,origin='document',metadata={'contribution_status':'self_attested_not_verified'})

    def files(self,owner,key,snapshot):
        with self.workspace._connection() as db:
            self._project(db,owner,key)
            row=db.execute('SELECT content_hash,origin,commit_sha FROM v3_project_snapshots WHERE project_id=? AND snapshot_id=?',(key,snapshot)).fetchone()
            if row is None:raise WorkspaceNotFound('snapshot_not_found')
            files={};manifest={}
            for f in db.execute('SELECT * FROM v3_project_files WHERE snapshot_id=? ORDER BY path',(snapshot,)):
                if sha256(f['text'].encode()).hexdigest()!=f['content_hash']:raise WorkspaceConflict('project_file_integrity_failed')
                files[f['path']]=f['text'];manifest[f['path']]=f['content_hash']
            if digest({'files':manifest,'origin':row['origin'],'commit_sha':row['commit_sha']})!=row['content_hash']:raise WorkspaceConflict('project_snapshot_integrity_failed')
            return files

    def delete_project(self,owner,key):
        with self.workspace._connection(write=True) as db:self._project(db,owner,key);db.execute('DELETE FROM v3_projects WHERE project_id=?',(key,))

    def read_file(self,owner,key,snapshot,path,*,db=None):
        """Check the manifest cheaply, then hash only the requested immutable text."""
        checked_path(path)
        with (nullcontext(db) if db is not None else self.workspace._connection()) as db:
            self._project(db,owner,key)
            version=db.execute('SELECT * FROM v3_project_snapshots WHERE project_id=? AND snapshot_id=?',(key,snapshot)).fetchone()
            if version is None:raise WorkspaceNotFound('snapshot_not_found')
            manifest={r['path']:r['content_hash'] for r in db.execute('SELECT path,content_hash FROM v3_project_files WHERE snapshot_id=? ORDER BY path',(snapshot,))}
            if digest({'files':manifest,'origin':version['origin'],'commit_sha':version['commit_sha']})!=version['content_hash']:raise WorkspaceConflict('project_snapshot_integrity_failed')
            row=db.execute('SELECT * FROM v3_project_files WHERE snapshot_id=? AND path=?',(snapshot,path)).fetchone()
            if row is None:raise WorkspaceNotFound('project_file_not_found')
            if sha256(row['text'].encode()).hexdigest()!=row['content_hash']:raise WorkspaceConflict('project_file_integrity_failed')
            return row['text'],dict(version)


def install_long_term_routes(app,workspace,owner,*,project_store=None):
    from job_agent.resume_workspace.project_import import MAX_ARCHIVE_BYTES
    store=LongTermRepository(workspace)
    @app.post('/api/v2/jobs',status_code=201)
    def create_job(request:JobCreate,user:str=Depends(owner)):return store.create_job(user,request)
    @app.get('/api/v2/jobs')
    def jobs(user:str=Depends(owner)):return store.list_jobs(user)
    @app.get('/api/v2/jobs/{key}')
    def job(key:str,user:str=Depends(owner)):return store.get_job(user,key)
    @app.post('/api/v2/jobs/{key}/events')
    def update_job(key:str,request:JobUpdate,user:str=Depends(owner)):return store.update_job(user,key,request)
    @app.post('/api/v2/jobs/{key}/links')
    def link_job(key:str,request:JobLink,user:str=Depends(owner)):return store.link_job(user,key,request)
    @app.delete('/api/v2/jobs/{key}',status_code=204)
    def delete_job(key:str,user:str=Depends(owner)):store.delete_job(user,key);return Response(status_code=204)
    projects=project_store or store
    @app.post('/api/v2/projects',status_code=201)
    def create_project(request:ProjectCreate,user:str=Depends(owner)):return projects.create_project(user,request)
    @app.get('/api/v2/projects')
    def list_projects(user:str=Depends(owner)):return projects.list_projects(user)
    @app.get('/api/v2/projects/{key}')
    def project(key:str,user:str=Depends(owner)):return projects.get_project(user,key)
    @app.post('/api/v2/projects/{key}/zip',status_code=201)
    async def import_zip(key:str,request:Request,user:str=Depends(owner)):
        from starlette.concurrency import run_in_threadpool
        projects.get_project(user,key)
        data=bytearray()
        async for chunk in request.stream():
            if len(data)+len(chunk)>MAX_ARCHIVE_BYTES:raise WorkspaceConflict('archive_upload_limit')
            data.extend(chunk)
        return await run_in_threadpool(projects.import_zip,user,key,bytes(data))
    @app.post('/api/v2/projects/{key}/documents',status_code=201)
    def document(key:str,request:ProjectDocument,user:str=Depends(owner)):return projects.add_document(user,key,request)
    @app.post('/api/v2/projects/{key}/github',status_code=201)
    def github(key:str,request:GitHubImport,user:str=Depends(owner)):return PublicGitHubImporter(projects).import_project(user,key,request)
    @app.get('/api/v2/projects/{key}/files')
    def files(key:str,snapshot:str=Query(min_length=1,max_length=100),user:str=Depends(owner)):
        return [{'path':p,'content_hash':sha256(t.encode()).hexdigest(),'lines':len(t.splitlines())} for p,t in projects.files(user,key,snapshot).items()]
    @app.delete('/api/v2/projects/{key}',status_code=204)
    def delete_project(key:str,user:str=Depends(owner)):projects.delete_project(user,key);return Response(status_code=204)
    return store

"""Small durable local task adapter. Does not claim the v1 PG/Redis deployment."""
from contextlib import asynccontextmanager
from threading import Event,Thread
from time import time
from uuid import uuid4
import json
from fastapi import Depends
from pydantic import Field
from job_agent.schemas import StrictModel
from job_agent.backend_service.contracts import RunStatus
from job_agent.resume_workspace.long_term import LongTermRepository,encoded,digest
from job_agent.resume_workspace.code_rag import CodeRAGService,INDEX_VERSION
from job_agent.resume_workspace.repository import WorkspaceConflict,WorkspaceNotFound

DDL='''
CREATE TABLE IF NOT EXISTS v3_tasks(
 task_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL,
 project_id TEXT NOT NULL REFERENCES v3_projects(project_id) ON DELETE CASCADE,
 snapshot_id TEXT NOT NULL REFERENCES v3_project_snapshots(snapshot_id) ON DELETE CASCADE,
 request_key TEXT NOT NULL, request_hash TEXT NOT NULL,index_version TEXT NOT NULL,
 status TEXT NOT NULL, stage TEXT NOT NULL, result TEXT,error_code TEXT,
 lease_token TEXT,lease_until REAL NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,
 created_at REAL NOT NULL,updated_at REAL NOT NULL,
 UNIQUE(owner_id,request_key));
CREATE INDEX IF NOT EXISTS v3_tasks_queue ON v3_tasks(status,lease_until,created_at);
'''


class IndexTaskRequest(StrictModel):
    request_key:str=Field(pattern=r'^[a-zA-Z0-9_-]{8,80}$')
    snapshot_id:str=Field(min_length=1,max_length=100)


class TaskRepository:
    atomic_publication=False
    def __init__(self,workspace,*,clock=time,lease_seconds=30,projects=None):
        self.workspace=workspace;self.projects=projects or LongTermRepository(workspace);self.clock=clock;self.lease_seconds=lease_seconds
        with workspace._connection(write=True) as db:db.executescript(DDL)

    def submit(self,owner,project_id,request):
        self.projects.files(owner,project_id,request.snapshot_id)
        hashed=digest({'project':project_id,'snapshot':request.snapshot_id,'kind':'code_index'})
        with self.workspace._connection(write=True) as db:
            self.projects._project(db,owner,project_id)
            old=db.execute('SELECT task_id,request_hash FROM v3_tasks WHERE owner_id=? AND request_key=?',(owner,request.request_key)).fetchone()
            if old:
                if old['request_hash']!=hashed:raise WorkspaceConflict('task_request_key_conflict')
                return old['task_id']
            active=db.execute("SELECT owner_id FROM v3_tasks WHERE status IN ('QUEUED','RUNNING')").fetchall()
            if len(active)>=20 or sum(r['owner_id']==owner for r in active)>=3:raise WorkspaceConflict('task_queue_quota_reached')
            tid='task-'+uuid4().hex;now=self.clock()
            db.execute('INSERT INTO v3_tasks(task_id,owner_id,project_id,snapshot_id,request_key,request_hash,index_version,status,stage,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',
                (tid,owner,project_id,request.snapshot_id,request.request_key,hashed,INDEX_VERSION,RunStatus.QUEUED.value,'queued',now,now))
            return tid

    def get(self,owner,task_id):
        with self.workspace._connection() as db:
            r=db.execute('SELECT * FROM v3_tasks WHERE owner_id=? AND task_id=?',(owner,task_id)).fetchone()
            if r is None:raise WorkspaceNotFound('task_not_found')
            result=json.loads(r['result']) if r['result'] else None
            return {k:r[k] for k in ('task_id','project_id','snapshot_id','status','stage','attempts','created_at','updated_at','error_code')}|{'result':result}

    def claim(self):
        with self.workspace._connection(write=True) as db:
            now=self.clock()
            db.execute("UPDATE v3_tasks SET status='FAILED',stage='stopped',error_code='worker_recovery_exhausted',lease_token=NULL,updated_at=? WHERE status='RUNNING' AND lease_until<=? AND attempts>=3",(now,now))
            r=db.execute("SELECT * FROM v3_tasks WHERE status='QUEUED' OR (status='RUNNING' AND lease_until<=? AND attempts<3) ORDER BY created_at LIMIT 1",(now,)).fetchone()
            if r is None:return None
            token=uuid4().hex
            db.execute("UPDATE v3_tasks SET status='RUNNING',stage='parsing',lease_token=?,lease_until=?,attempts=attempts+1,updated_at=? WHERE task_id=?",(token,now+self.lease_seconds,now,r['task_id']))
            return dict(r)|{'lease_token':token,'attempts':r['attempts']+1}

    def guard(self,db,claim):
        r=db.execute('SELECT status,lease_token,lease_until FROM v3_tasks WHERE task_id=?',(claim['task_id'],)).fetchone()
        if r is None or r['status']!='RUNNING' or r['lease_token']!=claim['lease_token'] or r['lease_until']<=self.clock():
            raise WorkspaceConflict('task_lease_lost')

    def heartbeat(self,claim):
        with self.workspace._connection(write=True) as db:
            self.guard(db,claim)
            db.execute('UPDATE v3_tasks SET lease_until=?,updated_at=? WHERE task_id=?',(self.clock()+self.lease_seconds,self.clock(),claim['task_id']))

    def complete(self,claim,result):
        with self.workspace._connection(write=True) as db:
            self.guard(db,claim)
            db.execute("UPDATE v3_tasks SET status='SUCCEEDED',stage='completed',result=?,lease_token=NULL,updated_at=? WHERE task_id=?",(encoded(result),self.clock(),claim['task_id']))

    def fail(self,claim,code):
        with self.workspace._connection(write=True) as db:
            self.guard(db,claim)
            db.execute("UPDATE v3_tasks SET status='FAILED',stage='stopped',error_code=?,lease_token=NULL,updated_at=? WHERE task_id=?",(code,self.clock(),claim['task_id']))

    def cancel(self,owner,task_id):
        with self.workspace._connection(write=True) as db:
            r=db.execute('SELECT status FROM v3_tasks WHERE owner_id=? AND task_id=?',(owner,task_id)).fetchone()
            if r is None:raise WorkspaceNotFound('task_not_found')
            if r['status']=='CANCELLED':return
            if r['status']!='QUEUED':raise WorkspaceConflict('only_queued_task_can_be_cancelled')
            db.execute("UPDATE v3_tasks SET status='CANCELLED',stage='cancelled',updated_at=? WHERE task_id=?",(self.clock(),task_id))

    def history(self,owner,project_id):
        with self.workspace._connection() as db:
            self.projects._project(db,owner,project_id)
            ids=[r[0] for r in db.execute('SELECT task_id FROM v3_tasks WHERE owner_id=? AND project_id=? ORDER BY created_at DESC LIMIT 100',(owner,project_id))]
        return [self.get(owner,tid) for tid in ids]


class IndexTaskWorker:
    def __init__(self,store,code,*,failpoint=None,external_dispatch=False):
        if getattr(store,'dispatch_mode','polling')=='redis' and not external_dispatch:raise WorkspaceConflict('polling_worker_disabled')
        self.store=store;self.code=code;self.failpoint=failpoint;self.stop_event=Event();self.thread=None

    def process_once(self):
        claim=self.store.claim()
        if claim is None:return False
        return self.process_claim(claim)

    def process_claim(self,claim):
        heartbeat_stop=Event()
        def heartbeat():
            while not heartbeat_stop.wait(max(.1,self.store.lease_seconds/3)):
                try:self.store.heartbeat(claim)
                except Exception:return
        renewer=Thread(target=heartbeat,daemon=True,name='local-index-lease');renewer.start()
        try:
            if claim['index_version']!=INDEX_VERSION:raise WorkspaceConflict('task_index_version_changed')
            if getattr(self.store,'atomic_publication',False):
                result=self.code.build(claim['owner_id'],claim['project_id'],claim['snapshot_id'],task_claim=claim)
            else:result=self.code.build(claim['owner_id'],claim['project_id'],claim['snapshot_id'],publish_guard=lambda db:self.store.guard(db,claim))
            if self.failpoint:self.failpoint('after_index_before_task_commit')
            if not getattr(self.store,'atomic_publication',False):self.store.complete(claim,result)
        except (WorkspaceNotFound,WorkspaceConflict) as exc:
            try:self.store.fail(claim,'source_unavailable_or_integrity_failed' if isinstance(exc,WorkspaceNotFound) else 'index_task_rejected')
            except WorkspaceConflict:pass # Old attempts cannot overwrite a new lease.
        except Exception:
            try:
                if getattr(self.store,'dispatch_mode','polling')=='redis':self.store.dispatch.retry(claim)
                else:self.store.fail(claim,'index_task_failed')
            except WorkspaceConflict:pass
        finally:
            heartbeat_stop.set();renewer.join(timeout=1)
        return True

    def start(self):
        if self.thread and self.thread.is_alive():return
        self.stop_event.clear()
        def loop():
            while not self.stop_event.is_set():
                try:worked=self.process_once()
                except Exception:worked=False # No raw source/exception in logs; persisted lease recovers.
                if not worked:self.stop_event.wait(.2)
        self.thread=Thread(target=loop,daemon=True,name='local-durable-index-worker');self.thread.start()

    def stop(self):
        self.stop_event.set()
        if self.thread:self.thread.join(timeout=5)


def install_task_routes(app,workspace,owner,code,*,worker_enabled=True,store=None):
    store=store or TaskRepository(workspace)
    redis_mode=getattr(store,'dispatch_mode','polling')=='redis'
    if redis_mode and worker_enabled:raise WorkspaceConflict('redis_requires_independent_worker')
    worker=None if redis_mode else IndexTaskWorker(store,code)
    app.state.task_store=store;app.state.index_worker=worker
    old_lifespan=app.router.lifespan_context
    @asynccontextmanager
    async def lifespan(application):
        async with old_lifespan(application):
            if worker_enabled and worker:worker.start()
            try:yield
            finally:
                if worker:worker.stop()
    app.router.lifespan_context=lifespan
    @app.post('/api/v2/projects/{project_id}/index-tasks',status_code=202)
    def submit(project_id:str,request:IndexTaskRequest,user:str=Depends(owner)):
        return store.get(user,store.submit(user,project_id,request))
    @app.get('/api/v2/tasks/{task_id}')
    def get(task_id:str,user:str=Depends(owner)):return store.get(user,task_id)
    @app.get('/api/v2/projects/{project_id}/index-tasks')
    def history(project_id:str,user:str=Depends(owner)):
        return store.history(user,project_id)[:20]
    @app.post('/api/v2/tasks/{task_id}/cancel')
    def cancel(task_id:str,user:str=Depends(owner)):
        store.cancel(user,task_id);return store.get(user,task_id)

