ALTER TABLE v3_projects ADD CONSTRAINT v3_current_snapshot_fk FOREIGN KEY(project_id,current_snapshot)
 REFERENCES v3_project_snapshots(project_id,snapshot_id) DEFERRABLE INITIALLY DEFERRED;
