CREATE TABLE v3_index_edges(publication_id TEXT NOT NULL REFERENCES v3_index_publications ON DELETE CASCADE,
 source_id TEXT NOT NULL,target_id TEXT NOT NULL,kind TEXT NOT NULL,line INTEGER NOT NULL,
